"""Actual fetch.yml proposal/cage shell over disposable Git remotes.

Transport fixture only: signing is explicitly disabled for fixture commits and the
gitsign/API programs model validation/PR metadata. No real quote is calculated, no
genuine signature or GitHub authorization is established, and no network is used.
"""
from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

import pytest
import yaml

ROOT = Path(__file__).resolve().parents[2]
WORKFLOW = ROOT / '.github/workflows/fetch.yml'
BRANCH = 'requote/driftwood-20261016'
QUOTE_PATHS = ['quote/driftwood/v1/feed.json', 'quote/driftwood/bump.yaml']


def scenario(tmp_path: Path, case: str) -> dict:
    real_git = shutil.which('git')
    assert real_git
    config = tmp_path / 'gitconfig'
    config.write_text('[user]\n name = transport fixture\n email = fixture@example.invalid\n'
                      '[commit]\n gpgsign = false\n[advice]\n detachedHead = false\n')
    env = dict(os.environ, GIT_CONFIG_GLOBAL=str(config), GIT_CONFIG_NOSYSTEM='1',
               GIT_TERMINAL_PROMPT='0', GIT_AUTHOR_DATE='2000-01-01T00:00:00Z',
               GIT_COMMITTER_DATE='2000-01-01T00:00:00Z')

    def git(*args: str, cwd: Path, check: bool = True) -> subprocess.CompletedProcess[str]:
        return subprocess.run([real_git, *args], cwd=cwd, env=env, text=True,
                              capture_output=True, check=check)

    remote, work = tmp_path / 'remote.git', tmp_path / 'work'
    git('init', '-q', '--bare', '-b', 'main', str(remote), cwd=tmp_path)
    git('clone', '-q', str(remote), str(work), cwd=tmp_path)
    for path in QUOTE_PATHS:
        (work / path).parent.mkdir(parents=True, exist_ok=True)
        (work / path).write_text('synthetic original bytes\n')
    (work / 'README.md').write_text('synthetic declaration\n')
    git('add', '-A', cwd=work)
    git('commit', '-qm', 'synthetic source', cwd=work)
    git('push', '-q', 'origin', 'main', cwd=work)
    source = git('rev-parse', 'HEAD', cwd=work).stdout.strip()
    original = ''
    existing = case not in {'fresh', 'staged-unrelated', 'collision', 'probe-error', 'create-refused'}
    if existing:
        git('checkout', '-qb', BRANCH, cwd=work)
        for path in QUOTE_PATHS:
            (work / path).write_text('synthetic generated bytes\n')
        if case == 'contaminated':
            (work / 'README.md').write_text('synthetic forbidden proposal declaration\n')
        git('add', '-A', cwd=work)
        git('-c', 'user.email=requote-bot@policy-as-versioned-insurer.invalid',
            'commit', '-qm', 'quote-driftwood: patch re-quote against exposure/v1.0.0', cwd=work)
        original = git('rev-parse', 'HEAD', cwd=work).stdout.strip()
        git('push', '-q', 'origin', BRANCH, cwd=work)
        git('checkout', '-q', 'main', cwd=work)
    for path in QUOTE_PATHS:
        (work / path).write_text('synthetic different computation\n' if 'mismatch' in case else
                                 'synthetic generated bytes\n')
    if case == 'staged-unrelated':
        (work / 'README.md').write_text('synthetic unrelated dirty declaration\n')
        git('add', 'README.md', cwd=work)

    state = tmp_path / 'prs.json'
    initial = []
    if case in {'open', 'open-mismatch', 'open-missing', 'closed', 'closed-mismatch', 'closed-missing', 'merged', 'merged-mismatch', 'head-mismatch'}:
        initial = [{'number': 1, 'state': 'CLOSED' if case.startswith('closed') else 'MERGED' if case.startswith('merged') else 'OPEN',
                    'headRefOid': source if case == 'head-mismatch' else original,
                    'url': 'https://example.invalid/fixture/pull/1'}]
    state.write_text(json.dumps(initial))
    if case in {'closed-missing', 'open-missing'}:
        git('push', '-q', 'origin', '--delete', BRANCH, cwd=work)
    calls = tmp_path / 'api-calls.jsonl'
    runner = tmp_path / 'runner'
    runner.mkdir()
    binaries = tmp_path / 'bin'
    binaries.mkdir()
    (binaries / 'date').write_text('#!/bin/sh\nprintf 20261016\n')
    (binaries / 'gitsign').write_text('#!/bin/sh\n[ "$FIXTURE_SIGNATURE_REFUSED" != yes ]\n')
    (binaries / 'git').write_text(f'#!{sys.executable}\n' + r'''
import os,pathlib,subprocess,sys
args=sys.argv[1:]
if os.environ.get('FIXTURE_PROBE_ERROR')=='yes' and args[:1]==['ls-remote']:
    raise SystemExit(128)
if os.environ.get('FIXTURE_COMPARE_ERROR')=='yes' and args[:1]==['diff'] and '--quiet' in args:
    raise SystemExit(128)
if os.environ.get('FIXTURE_COLLISION')=='yes' and 'push' in args:
    marker=pathlib.Path(os.environ['FIXTURE_RUNNER'])/'collision'
    if not marker.exists():
        marker.touch()
        subprocess.run([os.environ['FIXTURE_REAL_GIT'],'--git-dir',os.environ['FIXTURE_REMOTE'],
            'update-ref','refs/heads/'+os.environ['FIXTURE_BRANCH'],os.environ['FIXTURE_SOURCE']],check=True)
os.execv(os.environ['FIXTURE_REAL_GIT'],[os.environ['FIXTURE_REAL_GIT'],*args])
''')
    (binaries / 'gh').write_text(f'#!{sys.executable}\n' + r'''
import json,os,pathlib,subprocess,sys
args=sys.argv[1:]
state=pathlib.Path(os.environ['FIXTURE_PRS'])
with open(os.environ['FIXTURE_CALLS'],'a') as out: out.write(json.dumps(args)+'\n')
if args[:2]==['pr','list']:
    if os.environ.get('FIXTURE_API_REFUSED')=='yes': raise SystemExit('synthetic API read refusal')
    print(state.read_text()); raise SystemExit
if args[:2]!=['pr','create']: raise SystemExit('fixture permits only PR list/create')
if os.environ.get('FIXTURE_CREATE_REFUSED')=='yes': raise SystemExit('synthetic PR create refusal')
opts=dict(zip(args[2::2],args[3::2]))
assert opts['--base']=='main' and opts['--head']==os.environ['FIXTURE_BRANCH']
if '--repo' in opts: assert opts['--repo']=='fixture/insurer'
head=subprocess.check_output([os.environ['FIXTURE_REAL_GIT'],'--git-dir',os.environ['FIXTURE_REMOTE'],
    'rev-parse','refs/heads/'+opts['--head']],text=True).strip()
assert not json.loads(state.read_text()),'synthetic duplicate PR'
body=pathlib.Path(opts['--body-file']).read_text() if '--body-file' in opts else opts['--body']
state.write_text(json.dumps([dict(number=1,state='OPEN',headRefOid=head,
    url='https://example.invalid/fixture/pull/1',body=body)]))
print('https://example.invalid/fixture/pull/1')
''')
    for executable in binaries.iterdir():
        executable.chmod(0o755)
    env.update(PATH=str(binaries) + os.pathsep + env['PATH'], ADOPTER='driftwood', BUMP='patch',
               PREMIUM='synthetic fixture, not a price', TAG='exposure/v1.0.0', GH_TOKEN='not-a-token',
               GITHUB_REPOSITORY='fixture/insurer', RUNNER_TEMP=str(runner),
               FIXTURE_PRS=str(state), FIXTURE_CALLS=str(calls), FIXTURE_REMOTE=str(remote),
               FIXTURE_BRANCH=BRANCH, FIXTURE_SOURCE=source, FIXTURE_REAL_GIT=real_git,
               FIXTURE_RUNNER=str(runner), FIXTURE_COLLISION='yes' if case == 'collision' else 'no',
               FIXTURE_PROBE_ERROR='yes' if case == 'probe-error' else 'no',
               FIXTURE_COMPARE_ERROR='yes' if case == 'compare-error' else 'no',
               FIXTURE_SIGNATURE_REFUSED='yes' if case == 'signature-refused' else 'no',
               FIXTURE_API_REFUSED='yes' if case == 'api-refused' else 'no',
               FIXTURE_CREATE_REFUSED='yes' if case == 'create-refused' else 'no')
    steps = yaml.safe_load(WORKFLOW.read_text())['jobs']['requote']['steps']
    proposal = next(s['run'] for s in steps if str(s.get('name', '')).startswith('propose the re-quote'))
    cage = next(s['run'] for s in steps if str(s.get('name', '')).startswith('the observation cage'))
    # Declared fixture-only substitution: do not invoke any operator signing key.
    proposal = proposal.replace('commit -S ', 'commit --no-gpg-sign ')
    proposed = subprocess.run(['bash', '-e', '-c', proposal], cwd=work, env=env, text=True, capture_output=True)
    caged = subprocess.run(['bash', '-e', '-c', cage], cwd=work, env=env, text=True, capture_output=True)
    after = git('rev-parse', '--verify', 'refs/heads/' + BRANCH, cwd=remote, check=False).stdout.strip()
    changed = git('diff', '--name-only', source, after, cwd=remote).stdout.splitlines() if after else []
    return {'proposal_rc': proposed.returncode, 'cage_rc': caged.returncode,
            'output': proposed.stdout + proposed.stderr + caged.stdout + caged.stderr,
            'original': original, 'after': after, 'source': source,
            'main': git('rev-parse', 'refs/heads/main', cwd=remote).stdout.strip(),
            'prs': json.loads(state.read_text()), 'changed': changed,
            'dirty': git('status', '--porcelain', cwd=work).stdout,
            'api_calls': [json.loads(s) for s in calls.read_text().splitlines()] if calls.exists() else []}


@pytest.mark.parametrize('case', ['orphan', 'open'])
def test_existing_branch_is_not_mistaken_for_a_published_pr_and_owned_changes_are_cleaned(tmp_path: Path, case: str) -> None:
    r = scenario(tmp_path, case)
    assert r['proposal_rc'] == r['cage_rc'] == 0, r['output']
    assert r['after'] == r['original'] and r['main'] == r['source']
    assert len(r['prs']) == 1 and r['prs'][0]['headRefOid'] == r['original']
    assert not r['dirty']


@pytest.mark.parametrize('case', ['orphan-mismatch', 'open-mismatch', 'closed-mismatch', 'merged-mismatch'])
def test_different_computation_remains_explicitly_pending_without_rewriting_the_original(tmp_path: Path, case: str) -> None:
    r = scenario(tmp_path, case)
    assert r['proposal_rc'] != 0 and r['cage_rc'] == 0, r['output']
    assert 'PENDING' in r['output'] and 'different' in r['output']
    assert r['after'] == r['original'] and len(r['prs']) == 1
    assert r['prs'][0]['headRefOid'] == r['original'] and not r['dirty']


@pytest.mark.parametrize('case', ['closed', 'merged'])
def test_closed_proposal_lifecycle_is_respected_without_reopening(tmp_path: Path, case: str) -> None:
    r = scenario(tmp_path, case)
    assert r['proposal_rc'] == r['cage_rc'] == 0, r['output']
    assert r['after'] == r['original'] and len(r['prs']) == 1 and r['prs'][0]['state'] != 'OPEN'
    assert not any(call[:2] == ['pr', 'create'] for call in r['api_calls']) and not r['dirty']


def test_fresh_proposal_commits_only_the_owned_paths_and_leaves_main_unchanged(tmp_path: Path) -> None:
    r = scenario(tmp_path, 'fresh')
    assert r['proposal_rc'] == r['cage_rc'] == 0, r['output']
    assert r['main'] == r['source'] and r['changed'] == sorted(QUOTE_PATHS)
    assert len(r['prs']) == 1 and not r['dirty']


def test_unrelated_staged_declaration_still_fails_the_cage_and_never_enters_the_proposal(tmp_path: Path) -> None:
    r = scenario(tmp_path, 'staged-unrelated')
    assert r['cage_rc'] != 0 and 'README.md' in r['dirty'], r['output']
    assert r['main'] == r['source'] and 'README.md' not in r['changed']


def test_fresh_ref_creation_uses_an_absence_lease_even_for_a_fast_forward_collision(tmp_path: Path) -> None:
    r = scenario(tmp_path, 'collision')
    assert r['proposal_rc'] != 0 and r['cage_rc'] == 0, r['output']
    assert r['after'] == r['source'] and not r['prs'] and not r['dirty']


@pytest.mark.parametrize('case', ['probe-error', 'api-refused', 'signature-refused', 'contaminated', 'head-mismatch', 'compare-error'])
def test_unverifiable_transport_or_proposal_stays_pending_and_does_not_create_a_pr(tmp_path: Path, case: str) -> None:
    r = scenario(tmp_path, case)
    assert r['proposal_rc'] != 0 and r['cage_rc'] == 0, r['output']
    assert not any(call[:2] == ['pr', 'create'] for call in r['api_calls']) and not r['dirty']
    assert r['after'] == (r['original'] or '')


def test_pr_creation_refusal_keeps_a_durable_original_and_cleans_only_generated_paths(tmp_path: Path) -> None:
    r = scenario(tmp_path, 'create-refused')
    assert r['proposal_rc'] != 0 and r['cage_rc'] == 0, r['output']
    assert r['after'] and not r['prs'] and not r['dirty'] and r['main'] == r['source']


@pytest.mark.parametrize('case', ['closed-missing', 'open-missing'])
def test_a_deleted_proposal_branch_is_never_recreated_under_an_existing_pr(tmp_path: Path, case: str) -> None:
    r = scenario(tmp_path, case)
    assert r['cage_rc'] == 0 and not r['after'] and not r['dirty'], r['output']
    assert (r['proposal_rc'] == 0) == (case == 'closed-missing')
    assert not any(call[:2] == ['pr', 'create'] for call in r['api_calls'])
